"""Querying and adjusting the privileges held by the current process.

Everything here is read from the process token itself -- the array of
``LUID_AND_ATTRIBUTES`` the kernel keeps -- and never from the output of a
command-line tool.  Two facts about that array drive the whole module:

* every privilege the token holds has an entry in it, whether it is switched on
  or off, so the array *is* the inventory; and
* each entry carries ``SE_PRIVILEGE_ENABLED`` (plus a few bookkeeping bits), so
  "held" and "on" are two different answers about the same entry.

``has_privilege()`` answers the first question and ``privileges()`` the second.
"""

import operator
import os
from contextlib import contextmanager

from . import _winapi
from .errors import WTokenError

#: The attribute bit that says the privilege is switched on right now.
SE_PRIVILEGE_ENABLED = _winapi.SE_PRIVILEGE_ENABLED

#: A LUID is two 32-bit halves; anything wider cannot be one.
_MAX_LUID = (1 << 32) - 1

#: The system's "there is no such privilege" answers.
_NO_SUCH_PRIVILEGE = frozenset(
    (_winapi.ERROR_NO_SUCH_PRIVILEGE, 1312)  # ERROR_NO_SUCH_LOGON_SESSION
)


def _error_code(exc):
    """Return the Win32 error code an :class:`OSError` carries, if it has one."""
    return getattr(exc, "winerror", None) or getattr(exc, "errno", None)


def _raise_os(exc, what, privilege=None):
    """Turn a failed system call into ``WTokenError(kind="os")``."""
    message = getattr(exc, "strerror", None) or str(exc)
    error = WTokenError("%s: %s" % (what, message), kind="os", privilege=privilege)
    error.winerror = getattr(exc, "winerror", None)
    error.errno = getattr(exc, "errno", None)
    raise error from exc


def _raise_unknown_name(name):
    raise WTokenError(
        "no privilege called %r exists on this system" % (name,),
        kind="badarg",
        privilege=name,
    )


def _require_windows(what):
    """Refuse, with a classified error, to pretend on a non-Windows kernel."""
    if not _winapi.is_windows():
        raise WTokenError(
            "%s needs a Windows process token (os.name is %r)" % (what, os.name),
            kind="unsupported",
        )


def _check_name(name, what):
    """Return ``name`` when it can be a privilege name at all."""
    if not isinstance(name, str) or not name:
        raise WTokenError(
            "%s needs a non-empty privilege name, got %r" % (what, name),
            kind="badarg",
            privilege=name,
        )
    return name


def _check_enabled(enabled):
    """Return ``enabled`` as a plain boolean, or say why it cannot be one."""
    if isinstance(enabled, bool):
        return enabled
    if isinstance(enabled, int) and enabled in (0, 1):
        return bool(enabled)
    raise WTokenError(
        "enabled must be True or False, got %r" % (enabled,), kind="badarg"
    )


def _check_luid(luid):
    """Return ``luid`` as the integer the system identifies a privilege by."""
    if isinstance(luid, bool):
        raise WTokenError(
            "a privilege identifier must be an integer, got %r" % (luid,), kind="badarg"
        )
    try:
        value = operator.index(luid)
    except TypeError:
        raise WTokenError(
            "a privilege identifier must be an integer, got %r" % (luid,), kind="badarg"
        ) from None
    if not 0 <= value <= _MAX_LUID:
        raise WTokenError(
            "a privilege identifier is at most 32 bits wide, got %d" % value, kind="badarg"
        )
    return value


@contextmanager
def _token(access=_winapi.TOKEN_QUERY):
    """Hold the current process token open for the length of one operation."""
    _require_windows("reading the process token")
    try:
        handle = _winapi.open_process_token(access)
    except OSError as exc:
        _raise_os(exc, "the process token could not be opened")
    try:
        yield handle
    finally:
        _winapi.close_handle(handle)


def _read_table(handle):
    """Return ``[(name, enabled, attributes, luid), ...]`` off ``handle``."""
    try:
        entries = _winapi.get_token_privileges(handle)
    except OSError as exc:
        _raise_os(exc, "the privilege table could not be read")

    table = []
    for luid, attributes in entries:
        try:
            name = _winapi.lookup_privilege_name(luid)
        except OSError as exc:
            _raise_os(exc, "privilege %d could not be named" % luid)
        table.append((name, bool(attributes & SE_PRIVILEGE_ENABLED), attributes, luid))
    return table


def privileges():
    """Return ``{name: enabled}`` for every privilege the token holds.

    The mapping holds one entry per privilege on the token -- including the ones
    that are switched off -- and the value says whether that privilege is
    switched on *right now*.  Use :func:`has_privilege` when the question is
    only whether the token holds it at all.
    """
    with _token() as handle:
        return dict((entry[0], entry[1]) for entry in _read_table(handle))


def has_privilege(name):
    """Return ``True`` when the token holds ``name``, on or off.

    This answers "is the capability in the token", not "could the process use it
    this instant": a privilege that is held but switched off is still held, and
    is reported as ``False`` by :func:`privileges`.
    """
    name = _check_name(name, "has_privilege")
    with _token() as handle:
        held = set(entry[0] for entry in _read_table(handle))
    return name in held


def set_privilege(name, enabled=True):
    """Switch a held privilege on or off, and return whether it is on now.

    The token is asked for the privilege's state again once the adjustment has
    been made, so the value returned is the state the kernel recorded and not a
    guess.  A privilege the token does not hold cannot be switched on -- that is
    reported as ``WTokenError(kind="badarg")`` rather than quietly ignored.
    """
    name = _check_name(name, "set_privilege")
    enabled = _check_enabled(enabled)
    _require_windows("adjusting the process token")

    try:
        luid = _winapi.lookup_privilege_value(name)
    except OSError as exc:
        if _error_code(exc) in _NO_SUCH_PRIVILEGE:
            _raise_unknown_name(name)
        _raise_os(exc, "the privilege could not be looked up", name)

    access = _winapi.TOKEN_QUERY | _winapi.TOKEN_ADJUST_PRIVILEGES
    with _token(access) as handle:
        held = set(entry[3] for entry in _read_table(handle))
        if luid not in held:
            raise WTokenError(
                "the token does not hold %r, so it cannot be switched %s"
                % (name, "on" if enabled else "off"),
                kind="badarg",
                privilege=name,
            )
        try:
            _winapi.adjust_token_privileges(handle, luid, enabled)
            table = _read_table(handle)
        except OSError as exc:
            _raise_os(exc, "the privilege could not be adjusted", name)

    for entry_name, entry_enabled, _, entry_luid in table:
        if entry_luid == luid:
            return entry_enabled
    raise WTokenError(
        "the token lost %r while it was being adjusted" % (name,),
        kind="os",
        privilege=name,
    )


def privilege_luid(name):
    """Return the identifier the system uses for a privilege name.

    The value is the ``LUID`` of ``name`` on this machine -- the same number
    ``LookupPrivilegeValue`` hands out everywhere else -- so it can be passed to
    :func:`privilege_name` to get the name back.
    """
    name = _check_name(name, "privilege_luid")
    _require_windows("translating a privilege name")
    try:
        return _winapi.lookup_privilege_value(name)
    except OSError as exc:
        if _error_code(exc) in _NO_SUCH_PRIVILEGE:
            _raise_unknown_name(name)
        _raise_os(exc, "the privilege could not be looked up", name)


def privilege_name(luid):
    """Return the privilege name for an identifier.

    The inverse of :func:`privilege_luid`; an identifier no privilege on this
    system carries is reported as ``WTokenError(kind="badarg")``.
    """
    luid = _check_luid(luid)
    _require_windows("translating a privilege identifier")
    try:
        return _winapi.lookup_privilege_name(luid)
    except OSError as exc:
        if _error_code(exc) in _NO_SUCH_PRIVILEGE:
            raise WTokenError(
                "no privilege has the identifier %d" % luid, kind="badarg"
            ) from exc
        _raise_os(exc, "the privilege identifier could not be resolved")
